/**
 * Writes Vimma's toolkit/branding/brandings.ftl from upstream's (spec firefox-surfaces-trim,
 * "Product names"). Surfer links src/ files over engine/, so the generated file replaces
 * upstream's in every document that loads it, including those that do not load brand.ftl.
 *
 * Only features Vimma ships as its own get neutral names (RENAME); Mozilla's own products keep
 * theirs (KEEP), because renaming them would claim them as Vimma's. A term whose value says
 * Firefox or Mozilla and that neither list decides stops the generator, so a Firefox bump
 * surfaces a new name instead of shipping it (tools/branding/test/brandings.test.mjs).
 *
 * CLI: node tools/branding/brandings.mjs [--check]   (npm run gen-brandings)
 */
import { spawnSync } from "node:child_process";
import { lstatSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("../../", import.meta.url));
const PATH = "toolkit/locales/en-US/toolkit/branding/brandings.ftl";
export const UPSTREAM = `${root}engine/${PATH}`;
export const GENERATED = `${root}src/${PATH}`;

/**
 * Features Vimma ships under its own name, and the neutral name each gets. Each reads in the
 * strings that use it: "Manage Address Bar Suggestions", "Start Page (Default)" (Vimma's start
 * page is what new tabs show), "Open Tab Overview", "Open Labs", Settings' "Translations".
 *
 * @type {Readonly<Record<string, string>>}
 */
export const RENAME = Object.freeze({
  "-firefox-suggest-brand-name": "Address Bar Suggestions",
  "-firefox-home-brand-name": "Start Page",
  "-firefoxview-brand-name": "Tab Overview",
  "-firefoxlabs-brand-name": "Labs",
  "-translations-brand-name": "Translations",
  "-screenshots-brand-name": "Screenshots",
});

/**
 * Mozilla's own products and services, whose names stay as upstream has them.
 *
 * @type {readonly string[]}
 */
export const KEEP = Object.freeze([
  "-monitor-brand-name",
  "-mozmonitor-brand-name",
  "-send-brand-name",
  "-mozilla-vpn-brand-name",
  "-profiler-brand-name",
  "-relay-brand-name",
  "-thunderbird-brand-name",
  "-fakespot-brand-full-name",
]);

const NOTICE =
  "# Generated by tools/branding/brandings.mjs from Firefox's brandings.ftl; do not edit.\n" +
  "# After a Firefox bump, run npm run gen-brandings (docs/rebase.md).\n";

/** A single-line term definition. */
const TERM = /^(-[a-z][\w-]*) = (.*)$/gm;

/**
 * Terms whose value says Firefox or Mozilla and that the mapping does not decide.
 *
 * @param {string} upstream upstream's brandings.ftl
 * @returns {string[]}
 */
export function undecidedTerms(upstream) {
  // A multi-line value (a select expression) starts on the next lines, indented.
  const values = new Map();
  let current = "";
  for (const line of upstream.split("\n")) {
    const term = /^(-[a-z][\w-]*) =(.*)$/.exec(line);
    if (term) {
      current = /** @type {string} */ (term[1]);
      values.set(current, term[2]);
    } else if (current && /^\s/.test(line)) {
      values.set(current, `${values.get(current)}\n${line}`);
    } else {
      current = "";
    }
  }
  return [...values]
    .filter(([, value]) => /Firefox|Mozilla/.test(value))
    .map(([term]) => term)
    .filter((term) => !(term in RENAME) && !KEEP.includes(term));
}

/**
 * Vimma's brandings.ftl: upstream's, with the renamed terms' values replaced and a notice after
 * the licence header.
 *
 * @param {string} upstream upstream's brandings.ftl
 * @returns {string}
 */
export function generate(upstream) {
  const undecided = undecidedTerms(upstream);
  if (undecided.length > 0) {
    throw new Error(
      `brandings.ftl: decide ${undecided.join(", ")} in RENAME or KEEP (tools/branding/brandings.mjs)`,
    );
  }
  const present = new Set([...upstream.matchAll(TERM)].map((m) => m[1]));
  const gone = Object.keys(RENAME).filter((term) => !present.has(term));
  if (gone.length > 0) {
    throw new Error(`brandings.ftl: upstream no longer defines ${gone.join(", ")}; update RENAME`);
  }
  const body = upstream.replace(TERM, (line, term) =>
    term in RENAME ? `${term} = ${RENAME[term]}` : line,
  );
  // After the first comment block (the licence header), so Fluent attaches the notice to no term.
  const end = body.indexOf("\n\n");
  return end < 0
    ? `${body}\n${NOTICE}`
    : `${body.slice(0, end + 1)}${NOTICE}${body.slice(end + 1)}`;
}

/**
 * Upstream's brandings.ftl, or null when engine/ lacks it. After `npm run import` the engine
 * path is Surfer's link to our file, so upstream's comes from the engine's own git; a CI engine
 * unpacked without history has none, and the e2e workflow reads it before importing.
 *
 * @returns {string | null}
 */
export function readUpstream() {
  let link;
  try {
    link = lstatSync(UPSTREAM).isSymbolicLink();
  } catch {
    return null;
  }
  if (!link) return readFileSync(UPSTREAM, "utf8");
  const git = spawnSync("git", ["-C", `${root}engine`, "show", `HEAD:${PATH}`], {
    encoding: "utf8",
  });
  return git.status === 0 ? git.stdout : null;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const upstream = readUpstream();
  if (upstream === null) {
    console.error(`gen-brandings: no upstream ${PATH} under engine/ (it needs the Firefox source)`);
    process.exit(1);
  }
  const out = generate(upstream);
  if (process.argv.includes("--check")) {
    let current = "";
    try {
      current = readFileSync(GENERATED, "utf8");
    } catch {
      // a missing file is stale
    }
    if (current !== out) {
      console.error(`gen-brandings: ${GENERATED} is stale; run npm run gen-brandings`);
      process.exit(1);
    }
  } else {
    mkdirSync(dirname(GENERATED), { recursive: true });
    writeFileSync(GENERATED, out);
    console.log(`gen-brandings: wrote ${GENERATED}`);
  }
}
